SELECT SUM(active) AS active, SUM(assigned) AS assigned,
  ROUND(100.0*SUM(active)/SUM(assigned),1) AS m01_pct
FROM user_funnel WHERE assigned = 1;

SELECT region, SUM(assigned) AS lf2, SUM(provisioned) AS lf3, SUM(active) AS lf4, SUM(engaged) AS lf5, SUM(habitual) AS lf6
FROM user_funnel WHERE region LIKE '%launch%'
GROUP BY region;

SELECT DISTINCT e.agent_id, r.build_type_used
FROM events_clean e JOIN agent_registry r ON r.agent_id = e.agent_id
WHERE e.event_type <> 'login' AND r.registered = 0;

SELECT SUM(active) AS active, SUM(assigned) AS assigned,
  ROUND(100.0*SUM(active)/SUM(assigned),1) AS m01_pct
FROM user_funnel WHERE assigned = 1;

SELECT i.agent_id, r.name, r.registered, r.build_type_used, SUM(i.qualifying) AS qualifying, COUNT(*) AS interactions
FROM interactions i LEFT JOIN agent_registry r ON r.agent_id = i.agent_id
GROUP BY i.agent_id ORDER BY qualifying DESC;

SELECT COUNT(*) AS interactions, SUM(qualifying) AS qualifying, COUNT(DISTINCT user_id) AS users,
  SUM(method='exact') AS exact
FROM interactions WHERE agent_id = 'AG-FRAUD-01';

SELECT region, ROUND(100.0*SUM(active)/SUM(assigned),1) AS m01_pct, ROUND(100.0*SUM(habitual)/SUM(assigned),1) AS m02_pct, SUM(assigned) AS assigned
FROM user_funnel WHERE assigned = 1
GROUP BY region HAVING SUM(assigned) >= 5 ORDER BY m01_pct DESC;

SELECT day/7 + 1 AS week, SUM(qualifying) AS qualifying, COUNT(DISTINCT user_id) AS users
FROM interactions WHERE 1=1
GROUP BY week ORDER BY week;

